// The demo picture "Sky": Poly Haven's Kloofendal 48d Partly Cloudy (Pure Sky), CC0, scaled to
// 1920 wide with ffmpeg (-vf scale=1920:-2 -q:v 4). It ships inside a script, as a data URL,
// because WebGL refuses an image file loaded by a page opened from a plain file.
(window.QRTZPictures = window.QRTZPictures || {}).sky = 'data:image/jpeg;base64,';
